begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text); grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('78000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email) values(pg_temp.i(1),'single-owner@example.invalid'),(pg_temp.i(2),'single-other@example.invalid');
insert into auth.sessions(id,user_id) values(pg_temp.i(1),pg_temp.i(1)),(pg_temp.i(2),pg_temp.i(2));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(1),'session_id',pg_temp.i(1))::text,true);
set local role authenticated;
select public.agri_command('bootstrap','{"name":"TEST single branch"}');
reset role;
create function pg_temp.org() returns uuid language sql stable as $$select organization_id from public.staff_memberships where user_id=pg_temp.i(1)$$;
create function pg_temp.branch(n integer) returns uuid language sql stable as $$select id from public.branches where organization_id=pg_temp.org() and code='B0'||n::text$$;
select set_config('test.single_org',pg_temp.org()::text,true),set_config('test.single_branch',pg_temp.branch(1)::text,true),set_config('test.archived_branch',pg_temp.branch(2)::text,true);
-- Configuration occurs only through a privileged maintenance connection, without user claims.
select set_config('request.jwt.claims','{}',true);
update public.branches set active=(id=pg_temp.branch(1)),management_locked=true,name=case when code='B01' then 'Magpet Branch' else name end where organization_id=pg_temp.org();
insert into tap_results select is((select count(*)::integer from public.branches where organization_id=pg_temp.org()),3,'Original branch rows remain for historical foreign keys');
insert into tap_results select is((select count(*)::integer from public.branches where organization_id=pg_temp.org() and active),1,'Exactly one branch remains active');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(1),'session_id',pg_temp.i(1))::text,true);
set local role authenticated;
insert into tap_results select is((select count(*)::integer from public.branches),1,'Owner and old clients list only the configured branch');
insert into tap_results select is((select name from public.branches),'Magpet Branch','Configured name is exact');
insert into tap_results select ok((select management_locked from public.branches),'Client receives a read-only management flag');
insert into tap_results select throws_ok($$select public.agri_command('create_branch',jsonb_build_object('organizationId',current_setting('test.single_org'),'newBranchId',pg_temp.i(99),'name','Extra'))$$,'42501','Branch configuration is fixed. Contact your service provider.','Owner cannot add a branch by RPC');
insert into tap_results select throws_ok($$select public.agri_command('rename_branch',jsonb_build_object('organizationId',current_setting('test.single_org'),'branchId',current_setting('test.single_branch'),'name','Changed'))$$,'42501','Branch configuration is fixed. Contact your service provider.','Owner cannot rename Magpet by RPC');
insert into tap_results select throws_ok($$select app_private.branch_command('rename_branch',jsonb_build_object('organizationId',current_setting('test.single_org'),'branchId',current_setting('test.single_branch'),'name','Changed'))$$,'42501','Branch configuration is fixed. Contact your service provider.','Private legacy command cannot bypass the branch trigger');
insert into tap_results select throws_ok($$select public.agri_command('snapshot',jsonb_build_object('organizationId',current_setting('test.single_org'),'branchId',current_setting('test.archived_branch')) )$$,'42501','This branch is no longer enabled. Keep original recovery records and contact your service provider.','Removed branch cannot download operating stock');
insert into tap_results select throws_ok($$select public.agri_command('dispatch_transfer',jsonb_build_object('organizationId',current_setting('test.single_org'),'branchId',current_setting('test.single_branch'),'destinationBranchId',current_setting('test.archived_branch')))$$,'42501','The destination branch is not enabled.','Transfers cannot target a removed branch');
insert into tap_results select throws_ok($$select public.agri_command('stock_loss_report',jsonb_build_object('organizationId',current_setting('test.single_org'),'branchId',current_setting('test.single_branch'),'allBranches',true))$$,'42501','Only the configured branch is enabled for this report.','All-branch reports cannot mix archived figures into the operating branch');
insert into tap_results select lives_ok($$select public.agri_command('snapshot',jsonb_build_object('organizationId',current_setting('test.single_org'),'branchId',current_setting('test.single_branch')))$$,'Magpet still downloads its catalog and stock');
insert into tap_results select ok(not has_table_privilege('authenticated','public.branches','update'),'No customer direct-update permission');
insert into tap_results select ok(not has_table_privilege('authenticated','public.branches','insert'),'No customer direct-insert permission');
insert into tap_results select ok(not has_table_privilege('authenticated','public.branches','delete'),'No customer direct-delete permission');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(2),'session_id',pg_temp.i(2))::text,true);
set local role authenticated;
insert into tap_results select is((select count(*)::integer from public.branches),0,'An unrelated account sees no branch configuration');
insert into tap_results select throws_ok($$select public.agri_command('rename_branch',jsonb_build_object('organizationId',current_setting('test.single_org'),'branchId',current_setting('test.single_branch'),'name','Changed'))$$,'42501','You do not have access to this branch','Cross-organization access remains denied');
reset role;
insert into tap_results select * from finish(); select line from tap_results;
rollback;
